'use client';

import { useState } from 'react';

import { CircleCheckIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { PROJECT, SPRINTS, type Sprint, type SprintId } from './data';
import {
  csvRowsOf,
  goalOf,
  needsAttention,
  rowsOf,
  sprintOf,
  totalsOf,
} from './figures';
import { GoalCard } from './goal-card';
import {
  ExportButton,
  PeriodSwitch,
  REPORT_SURFACE,
  ReportToolbar,
  downloadCsv,
  useSimulatedLoad,
  type PeriodOption,
} from './report-frame';
import { WorkstreamTable } from './workstream-table';

type RowFilter = 'all' | 'attention';

const SPRINT_OPTIONS: PeriodOption<SprintId>[] = SPRINTS.map((sprint) => ({
  id: sprint.id,
  label: `Sprint ${sprint.number}`,
}));

const CURRENT_SPRINT: SprintId = 's23';

const SKELETON_ROWS = ['first', 'second', 'third', 'fourth', 'fifth'];

function sprintKeyOf(sprintId: SprintId) {
  return sprintId;
}

function isRowFilter(value: unknown): value is RowFilter {
  const isAll = value === 'all';
  const isAttention = value === 'attention';
  return isAll || isAttention;
}

function peopleLabelOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

function blockedLabelOf(count: number) {
  if (count === 0) {
    return 'nothing blocked';
  }
  if (count === 1) {
    return '1 task blocked';
  }
  return `${count} tasks blocked`;
}

function workstreamCountOf(count: number) {
  if (count === 1) {
    return '1 workstream';
  }
  return `${count} workstreams`;
}

function calmLineOf(sprint: Sprint) {
  const isRunning = sprint.daysElapsed < sprint.workingDays;
  if (isRunning) {
    return `Every workstream is on track in sprint ${sprint.number}`;
  }
  return `Every workstream was on track in sprint ${sprint.number}`;
}

function visibleRowsOf<Row>(
  isAttentionView: boolean,
  rows: Row[],
  attentionRows: Row[]
) {
  if (isAttentionView) {
    return attentionRows;
  }
  return rows;
}

function totalsWhen<Value>(isShown: boolean, value: Value) {
  if (isShown) {
    return value;
  }
  return null;
}

function HealthSkeleton() {
  return (
    <div aria-hidden='true' className='flex flex-col gap-4'>
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-4 p-5')}>
        <Skeleton className='h-3 w-24' />
        <Skeleton className='h-4 w-64 max-w-full' />
        <Skeleton className='h-7 w-40' />
        <Skeleton className='h-2 w-full rounded-full' />
        <Skeleton className='h-3 w-56 max-w-full' />
      </div>
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-3 p-5')}>
        <Skeleton className='h-3.5 w-28' />
        {SKELETON_ROWS.map((row) => (
          <Skeleton key={row} className='h-8 w-full' />
        ))}
      </div>
    </div>
  );
}

export default function Dashboards03() {
  const load = useSimulatedLoad<SprintId>(CURRENT_SPRINT, sprintKeyOf);
  const [filter, setFilter] = useState<RowFilter>('all');
  const shownSprintId = load.loaded ?? load.requested;
  const sprint = sprintOf(shownSprintId);
  const rows = rowsOf(sprint);
  const totals = totalsOf(rows);
  const goal = goalOf(sprint, totals);
  const attentionRows = rows.filter(needsAttention);
  const isAttentionView = filter === 'attention';
  const visibleRows = visibleRowsOf(isAttentionView, rows, attentionRows);
  const isCalm = attentionRows.length === 0;
  const showsCalmState = isAttentionView && isCalm;
  const showsTotals = !isAttentionView;
  const shownTotals = totalsWhen(showsTotals, totals);
  const peopleLabel = peopleLabelOf(PROJECT.peopleCount);
  const meta = `${PROJECT.release} · ${sprint.rangeLabel} · ${peopleLabel}`;
  const workstreamLabel = workstreamCountOf(rows.length);
  const blockedLabel = blockedLabelOf(totals.blocked);
  const calmLine = calmLineOf(sprint);

  function changeFilter(value: unknown) {
    if (isRowFilter(value)) {
      setFilter(value);
    }
  }

  function showAll() {
    setFilter('all');
  }

  function exportHealth() {
    const csvRows = csvRowsOf(rows);
    const fileName = `${PROJECT.fileSlug}-sprint-${sprint.number}.csv`;
    downloadCsv(fileName, csvRows);
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <ReportToolbar title={PROJECT.name} meta={meta}>
        <ExportButton disabled={load.isFirstLoad} onExport={exportHealth} />
      </ReportToolbar>
      <div className='mx-auto flex w-full max-w-4xl flex-col gap-4 px-4 py-5 md:px-6'>
        <PeriodSwitch
          label='Sprint'
          options={SPRINT_OPTIONS}
          value={load.requested}
          isUpdating={load.isUpdating}
          onValueChange={load.request}
        />
        {load.isFirstLoad && <HealthSkeleton />}
        {!load.isFirstLoad && (
          <div aria-busy={load.isUpdating} className='flex flex-col gap-4'>
            <GoalCard sprint={sprint} goal={goal} />
            <section
              aria-label='Workstreams'
              className={cn(REPORT_SURFACE, 'flex flex-col gap-3 pt-4 pb-1')}
            >
              <div className='flex flex-wrap items-center justify-between gap-x-3 gap-y-2 px-4'>
                <div className='flex flex-col gap-0.5'>
                  <h2 className='text-sm font-medium'>Workstreams</h2>
                  <p className='text-muted-foreground text-xs tabular-nums'>
                    {`${workstreamLabel}, ${blockedLabel}`}
                  </p>
                </div>
                <Tabs value={filter} onValueChange={changeFilter}>
                  <TabsList
                    variant='segmented'
                    aria-label='Workstreams to show'
                  >
                    <TabsTab value='all'>All</TabsTab>
                    <TabsTab value='attention'>
                      Needs attention
                      <span className='text-muted-foreground text-xs tabular-nums'>
                        {attentionRows.length}
                      </span>
                    </TabsTab>
                  </TabsList>
                </Tabs>
              </div>
              <WorkstreamTable
                rows={visibleRows}
                totals={shownTotals}
                emptyState={
                  showsCalmState && (
                    <div className='flex flex-col items-center gap-3 px-4 py-10 text-center'>
                      <span className='keycap-3d text-success-foreground flex size-9 items-center justify-center rounded-lg'>
                        <CircleCheckIcon />
                      </span>
                      <p className='text-[13px] font-medium text-balance'>
                        {calmLine}
                      </p>
                      <Button variant='outline' size='sm' onClick={showAll}>
                        Show all workstreams
                      </Button>
                    </div>
                  )
                }
              />
            </section>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Sprint } from './data';
import { percentAmountOf, type Goal, type GoalTone } from './figures';

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const MARKER_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const MARKER_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const INSTANT: Transition = { duration: 0 };

const VERDICT_TONE: Record<GoalTone, string> = {
  good: 'text-success-foreground',
  behind: 'text-warning-foreground',
  neutral: 'text-foreground',
};

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function taskWordOf(count: number) {
  if (count === 1) {
    return 'task';
  }
  return 'tasks';
}

function percentTextOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

type GoalMeterProps = {
  goal: Goal;
  transition: Transition;
};

/** Done against planned, with a marker where the team should be by today. Both slide into place. */
function GoalMeter({ goal, transition }: GoalMeterProps) {
  const hiddenShare = 1 - goal.share;
  const hiddenText = percentTextOf(hiddenShare);
  const fillOffset = `-${hiddenText}`;
  const taskWord = taskWordOf(goal.planned);
  const valueText = `${goal.done} of ${goal.planned} ${taskWord} done`;
  const hasMarker = goal.expectedShare !== null;
  const markerShare = goal.expectedShare ?? 0;
  const markerOffset = percentTextOf(markerShare);

  return (
    <div
      role='progressbar'
      aria-label='Sprint progress'
      aria-valuemin={0}
      aria-valuemax={goal.planned}
      aria-valuenow={goal.done}
      aria-valuetext={valueText}
      className='bg-foreground/[0.08] relative h-2 rounded-full'
    >
      <span className='absolute inset-0 overflow-hidden rounded-full'>
        <motion.span
          initial={false}
          animate={{ x: fillOffset }}
          transition={transition}
          className='bg-primary absolute inset-0 rounded-full'
        />
      </span>
      <AnimatePresence initial={false}>
        {hasMarker && (
          <motion.span
            key='marker'
            aria-hidden='true'
            initial={{ opacity: 0, x: markerOffset }}
            animate={{
              opacity: 1,
              x: markerOffset,
              transition: { opacity: MARKER_IN, x: transition },
            }}
            exit={{ opacity: 0, transition: MARKER_OUT }}
            className='pointer-events-none absolute -inset-y-1 left-0 w-full'
          >
            <span className='bg-foreground ring-card absolute inset-y-0 left-0 w-0.5 -translate-x-1/2 rounded-full ring-2' />
          </motion.span>
        )}
      </AnimatePresence>
    </div>
  );
}

type GoalCardProps = {
  sprint: Sprint;
  goal: Goal;
};

export function GoalCard({ sprint, goal }: GoalCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = moveTransitionOf(shouldReduceMotion);
  const shareAmount = percentAmountOf(goal.share);
  const hasMarker = goal.expectedShare !== null;
  const taskWord = taskWordOf(goal.planned);

  return (
    <section
      aria-label={`Sprint ${sprint.number} goal`}
      className='surface-brand flex flex-col gap-4 rounded-xl p-5'
    >
      <div className='flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1'>
        <p className='text-muted-foreground text-xs font-medium'>
          {`Sprint ${sprint.number} goal`}
        </p>
        <span className='text-muted-foreground text-xs'>
          Illustrative figures
        </span>
      </div>
      <p className='text-base font-semibold text-balance'>{sprint.goal}</p>
      <div className='flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1'>
        <p className='flex items-baseline gap-1.5'>
          <MotionNumber value={goal.done} className='text-2xl font-semibold' />
          <span className='text-muted-foreground text-[13px]'>of</span>
          <MotionNumber
            value={goal.planned}
            className='text-[13px] font-medium'
          />
          <span className='text-muted-foreground text-[13px]'>
            {`${taskWord} done`}
          </span>
        </p>
        <MotionNumber
          value={shareAmount}
          suffix='%'
          className='text-lg font-semibold'
        />
      </div>
      <GoalMeter goal={goal} transition={transition} />
      <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-xs'>
        <span className={cn('font-medium', VERDICT_TONE[goal.tone])}>
          {goal.verdict}
        </span>
        <span className='text-muted-foreground flex items-center gap-1.5'>
          {hasMarker && (
            <span
              aria-hidden='true'
              className='bg-foreground inline-block h-2.5 w-0.5 rounded-full'
            />
          )}
          {goal.timeLine}
        </span>
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';

import { HEALTH_META, type Lead } from './data';
import { percentAmountOf, type Totals, type WorkstreamRow } from './figures';

const TABLE_GRID =
  'grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 px-4 sm:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)_2.75rem_2.75rem_3.5rem_minmax(5.5rem,1fr)_6rem]';

const WIDE_CELL = 'hidden sm:flex';

const FIGURE_CELL = 'hidden justify-end text-[13px] sm:flex';

const ROW_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const ROW_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

const ROW_VARIANTS: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: ROW_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ROW_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: ROW_OUT },
  shown: { opacity: 1, transition: ROW_IN },
};

function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_VARIANTS;
}

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function firstNameOf(lead: Lead) {
  const [firstName] = lead.name.split(' ');
  return firstName;
}

type FigureProps = {
  value: number;
  isQuiet?: boolean;
};

function Figure({ value, isQuiet }: FigureProps) {
  return (
    <MotionNumber
      value={value}
      className={cn(isQuiet && 'text-muted-foreground')}
    />
  );
}

type ProgressCellProps = {
  share: number;
  transition: Transition;
};

function ProgressCell({ share, transition }: ProgressCellProps) {
  const hiddenShare = 1 - share;
  const hiddenPercent = hiddenShare * 100;
  const offset = `-${hiddenPercent}%`;
  const shareAmount = percentAmountOf(share);

  return (
    <div role='cell' className={cn(WIDE_CELL, 'items-center gap-2')}>
      <span className='bg-foreground/[0.08] relative block h-1 min-w-0 flex-1 overflow-hidden rounded-full'>
        <motion.span
          initial={false}
          animate={{ x: offset }}
          transition={transition}
          className='bg-primary absolute inset-0 rounded-full'
        />
      </span>
      <MotionNumber
        value={shareAmount}
        suffix='%'
        className='text-muted-foreground w-9 justify-end text-xs'
      />
    </div>
  );
}

function LeadCell({ lead }: { lead: Lead }) {
  return (
    <div role='cell' className={cn(WIDE_CELL, 'min-w-0 items-center gap-2')}>
      <Avatar className='size-6 text-[10px]'>
        {lead.avatar && <AvatarImage src={lead.avatar} alt='' />}
        <AvatarFallback>{lead.initials}</AvatarFallback>
      </Avatar>
      <span className='truncate text-[13px]'>{firstNameOf(lead)}</span>
    </div>
  );
}

function HealthChip({ row }: { row: WorkstreamRow }) {
  const meta = HEALTH_META[row.health];

  return (
    <Chip color={meta.color}>
      <span aria-hidden='true' className='size-1.5 rounded-full bg-(--chip)' />
      {meta.label}
    </Chip>
  );
}

type WorkstreamTableProps = {
  rows: WorkstreamRow[];
  totals: Totals | null;
  emptyState?: React.ReactNode;
};

/** One grid for the header, the rows and the totals, so the figures line up. Rows enter and leave in place. */
export function WorkstreamTable({
  rows,
  totals,
  emptyState,
}: WorkstreamTableProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const transition = moveTransitionOf(shouldReduceMotion);

  return (
    <div role='table' aria-label='Workstreams' className='flex flex-col'>
      <div role='rowgroup'>
        <div
          role='row'
          className={cn(
            TABLE_GRID,
            'hairline-b border-border text-muted-foreground h-9 text-xs font-medium'
          )}
        >
          <span role='columnheader'>Workstream</span>
          <span role='columnheader' className={WIDE_CELL}>
            Lead
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Done
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Open
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Blocked
          </span>
          <span role='columnheader' className={WIDE_CELL}>
            Progress
          </span>
          <span
            role='columnheader'
            className='flex justify-end sm:justify-start'
          >
            Health
          </span>
        </div>
      </div>
      <div role='rowgroup' className='hairline-divide-y divide-border'>
        <AnimatePresence initial={false}>
          {rows.map((row) => {
            const isBlockFree = row.blocked === 0;
            const leadFirstName = firstNameOf(row.lead);
            const phoneLine = `${row.done} of ${row.planned} done · ${leadFirstName}`;

            return (
              <motion.div
                key={row.id}
                variants={rowVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <div role='row' className={cn(TABLE_GRID, 'min-h-12 py-2.5')}>
                  <div role='cell' className='flex min-w-0 flex-col gap-0.5'>
                    <span className='truncate text-[13px] font-medium'>
                      {row.name}
                    </span>
                    <span className='text-muted-foreground text-xs tabular-nums sm:hidden'>
                      {phoneLine}
                    </span>
                  </div>
                  <LeadCell lead={row.lead} />
                  <div role='cell' className={FIGURE_CELL}>
                    <Figure value={row.done} />
                  </div>
                  <div role='cell' className={FIGURE_CELL}>
                    <Figure value={row.open} />
                  </div>
                  <div role='cell' className={FIGURE_CELL}>
                    <Figure value={row.blocked} isQuiet={isBlockFree} />
                  </div>
                  <ProgressCell share={row.share} transition={transition} />
                  <div
                    role='cell'
                    className='flex justify-end sm:justify-start'
                  >
                    <HealthChip row={row} />
                  </div>
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
      {emptyState}
      {totals && (
        <div role='rowgroup'>
          <div
            role='row'
            className={cn(
              TABLE_GRID,
              'hairline-t border-border min-h-11 py-2.5 font-medium'
            )}
          >
            <span role='rowheader' className='text-[13px]'>
              All workstreams
            </span>
            <span role='cell' className={WIDE_CELL} />
            <div role='cell' className={FIGURE_CELL}>
              <Figure value={totals.done} />
            </div>
            <div role='cell' className={FIGURE_CELL}>
              <Figure value={totals.open} />
            </div>
            <div role='cell' className={FIGURE_CELL}>
              <Figure value={totals.blocked} />
            </div>
            <ProgressCell share={totals.share} transition={transition} />
            <span
              role='cell'
              className='text-muted-foreground flex justify-end text-xs tabular-nums sm:justify-start'
            >
              {`${totals.done} of ${totals.planned}`}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  CheckIcon,
  DownloadIcon,
  LoaderCircleIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

export const REPORT_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const FIRST_LOAD_MS = 900;

const UPDATE_MS = 450;

const EXPORTED_NOTICE_MS = 1600;

const FORMULA_PREFIXES = ['=', '+', '-', '@'];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const NOTE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const NOTE_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const NOTE_VARIANTS: Variants = {
  enter: { opacity: 0, x: -4 },
  visible: { opacity: 1, x: 0, transition: NOTE_IN },
  exit: { opacity: 0, transition: NOTE_OUT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: NOTE_IN },
  exit: { opacity: 0, transition: NOTE_OUT },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function noteVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return NOTE_VARIANTS;
}

function loadDelayOf(isFirstLoad: boolean) {
  if (isFirstLoad) {
    return FIRST_LOAD_MS;
  }
  return UPDATE_MS;
}

function loadedKeyOf<Query>(
  loaded: Query | null,
  keyOf: (query: Query) => string
) {
  if (loaded === null) {
    return null;
  }
  return keyOf(loaded);
}

/**
 * Stands in for a request: the first load shows a skeleton, a later change keeps the
 * previous result on screen until the next one arrives.
 */
export function useSimulatedLoad<Query>(
  initialQuery: Query,
  keyOf: (query: Query) => string
) {
  const [requested, setRequested] = useState(initialQuery);
  const [loaded, setLoaded] = useState<Query | null>(null);
  const isFirstLoad = loaded === null;
  const delay = loadDelayOf(isFirstLoad);
  const requestedKey = keyOf(requested);
  const loadedKey = loadedKeyOf(loaded, keyOf);
  const isUpdating = loadedKey !== null && loadedKey !== requestedKey;

  useEffect(() => {
    const timer = window.setTimeout(() => setLoaded(requested), delay);
    return () => window.clearTimeout(timer);
  }, [requested, delay]);

  return { requested, loaded, isFirstLoad, isUpdating, request: setRequested };
}

export type PeriodOption<Id extends string> = { id: Id; label: string };

type ReportToolbarProps = {
  title: string;
  meta: string;
  children?: React.ReactNode;
};

export function ReportToolbar({ title, meta, children }: ReportToolbarProps) {
  return (
